-- Exporta las reglas de acceso REALES de las tablas de Nexa (SOLO LECTURA; una sola sentencia): estado de RLS, TODAS las políticas, las funciones auxiliares pa_* (pa_uid, pa_role, pa_region, pa_xmode…) con su código,
-- privilegios por rol, columnas y disparadores. Con esto se reproducen localmente las reglas reales para probar E1 con todos los roles. No contiene datos de personas.
select json_build_object(
  'tablas', (select json_agg(x) from (select c.relname, c.relkind, c.relrowsecurity as rls, c.relforcerowsecurity as rls_forzada from pg_class c join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and c.relkind in ('r', 'v') and (c.relname like 'pa\_%' or c.relname like 'supervision%') order by 1) x),
  'politicas', (select json_agg(x) from (select tablename, policyname, permissive, roles, cmd, qual, with_check from pg_policies where schemaname = 'public' and (tablename like 'pa\_%' or tablename like 'supervision%') order by tablename, policyname) x),
  'funciones_pa', (select json_agg(x) from (select p.proname, p.prosecdef as security_definer, pg_get_functiondef(p.oid) as definicion from pg_proc p join pg_namespace n on n.oid = p.pronamespace where n.nspname = 'public' and p.proname like 'pa\_%' order by 1) x),
  'privilegios', (select json_agg(x) from (select table_name, grantee, string_agg(privilege_type, ',' order by privilege_type) as privilegios from information_schema.role_table_grants where table_schema = 'public' and (table_name like 'pa\_%' or table_name like 'supervision%') and grantee in ('anon', 'authenticated', 'service_role') group by 1, 2 order by 1, 2) x),
  'columnas', (select json_agg(x) from (select table_name, column_name, data_type, is_nullable, column_default from information_schema.columns where table_schema = 'public' and (table_name like 'pa\_%' or table_name like 'supervision%') order by table_name, ordinal_position) x),
  'disparadores', (select json_agg(x) from (select c.relname as tabla, t.tgname, pg_get_triggerdef(t.oid) as definicion from pg_trigger t join pg_class c on c.oid = t.tgrelid join pg_namespace n on n.oid = c.relnamespace where n.nspname = 'public' and not t.tgisinternal and (c.relname like 'pa\_%' or c.relname like 'supervision%') order by 1, 2) x),
  'llaves', (select json_agg(x) from (select conrelid::regclass::text as tabla, conname, contype, pg_get_constraintdef(oid) as definicion from pg_constraint where connamespace = 'public'::regnamespace and (conrelid::regclass::text like 'pa\_%' or conrelid::regclass::text like 'supervision%') order by 1, 2) x),
  'indices', (select json_agg(x) from (select tablename, indexname, indexdef from pg_indexes where schemaname = 'public' and (tablename like 'pa\_%' or tablename like 'supervision%') order by 1, 2) x)
) as politicas;
